// LastErrorMessage returns the most recent native panic message for this binding.
func LastErrorMessage() string {
	p := bindings().lastError()
	if p == nil {
		return ""
	}
	length := 0
	for *(*byte)(unsafe.Add(p, length)) != 0 {
		length++
	}
	return string(unsafe.Slice((*byte)(p), length))
}

